-- ---- 1. L'arbre : la sous-notion « ratio » (Situations de proportionnalité) --

insert into public.classification_nodes (kind, parent_id, name, position)
select 'subnotion', n.id, 'ratio',
       (select coalesce(max(c.position), -1) + 1 from public.classification_nodes c where c.parent_id = n.id)
  from public.classification_nodes n
 where n.kind = 'notion' and n.name = 'Situations de proportionnalité'
   and n.parent_id = (select id from public.classification_nodes where kind = 'branch' and name = 'Proportionnalité');

