-- ---- 4. Vérifications (la migration échoue si le compte n'y est pas) --------

do $check$
declare
	v5 integer; v4 integer; v3 integer;
	v_sans_noeud integer;
	r5 integer; r4 integer; r3 integer;
	v_flu integer; v_algo integer; v_demo integer;
begin
	select count(*) into v5 from public.curriculum_points where grade = '5';
	select count(*) into v4 from public.curriculum_points where grade = '4';
	select count(*) into v3 from public.curriculum_points where grade = '3';
	select count(*) into v_sans_noeud from public.curriculum_points
	 where grade in ('5','4','3') and node_id is null;
	select count(*) into r5 from public.curriculum_point_automatismes where grade = '5';
	select count(*) into r4 from public.curriculum_point_automatismes where grade = '4';
	select count(*) into r3 from public.curriculum_point_automatismes where grade = '3';
	select count(*) into v_flu from public.curriculum_points
	 where grade in ('5','4','3') and regime_acquisition = 'fluence';
	select count(*) into v_algo from public.curriculum_points
	 where grade in ('5','4','3') and kind = 'algorithme';
	select count(*) into v_demo from public.curriculum_points
	 where grade in ('5','4','3') and kind = 'demonstration';
	if v5 <> 106 or v4 <> 69 or v3 <> 51 or v_sans_noeud <> 0
	   or r5 <> 44 or r4 <> 40 or r3 <> 34
	   or v_flu <> 5 or v_algo <> 18 or v_demo <> 4 then
		raise exception 'seed cycle 4 incohérent : 5e=%, 4e=%, 3e=%, sans nœud=%, réfs=%/%/%, flu=%, algo=%, dém=%',
			v5, v4, v3, v_sans_noeud, r5, r4, r3, v_flu, v_algo, v_demo;
	end if;
	if not exists (select 1 from public.classification_nodes c
	                 join public.classification_nodes p on p.id = c.parent_id
	                 join public.classification_nodes b on b.id = p.parent_id
	                where c.kind = 'subnotion' and c.name = 'ratio'
	                  and p.name = 'Situations de proportionnalité'
	                  and b.name = 'Proportionnalité') then
		raise exception 'sous-notion « ratio » absente';
	end if;
end $check$;
